package com.bank.loyalty;

import java.math.BigInteger;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FibonacciDemo {

    private static final Logger log = Logger.getLogger(FibonacciDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FibonacciCalculator calculator = new FibonacciCalculator();

        // Naive recursion — fine for small months, shown for concept.
        for (int month = 0; month <= 10; month++) {
            long points = calculator.fibNaive(month);
            log.info("Month " + month + " loyalty points (naive): " + points);
        }

        // Memoized recursion with BigInteger — safe for a large month.
        int bigMonth = 100;
        BigInteger bigPoints = calculator.fibMemo(bigMonth);
        log.info(() -> "Month " + bigMonth + " loyalty points (memoized): " + bigPoints);
    }
}

