class FibonacciCalculator {

    private static final Logger log = Logger.getLogger(FibonacciCalculator.class.getName());

    // A cache so each month is computed only once (memoization).
    private final java.util.Map<Integer, BigInteger> memo = new java.util.HashMap<>();

    // Naive recursion: simple but exponential. Only for small n.
    long fibNaive(int n) {
        if (n < 0) throw new IllegalArgumentException("Month cannot be negative: " + n);
        if (n == 0) return 0L;          // BASE CASE 1
        if (n == 1) return 1L;          // BASE CASE 2
        return fibNaive(n - 1) + fibNaive(n - 2); // RECURSIVE CASE
    }

    // Memoized recursion: each value computed once, uses BigInteger.
    BigInteger fibMemo(int n) {
        if (n < 0) throw new IllegalArgumentException("Month cannot be negative: " + n);
        if (n == 0) return BigInteger.ZERO;
        if (n == 1) return BigInteger.ONE;
        if (memo.containsKey(n)) {
            return memo.get(n);          // reuse stored answer instantly
        }
        BigInteger result = fibMemo(n - 1).add(fibMemo(n - 2));
        memo.put(n, result);             // cache for reuse
        return result;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
